  <div class="module-theme min-h-screen flex" :class="[department === 'inventory' ? 'inventory-page' : 'bg-slate-900 text-slate-100', { 'inventory-receiving-page': department === 'inventory' && page === 'receiving', 'purchase-orders-page': isClinicPurchaseOrders, 'finance-page': department === 'finance', 'finance-budget-workspace': department === 'finance' && page === 'budgets' }]">
    <OwnerSidebar />
    <main v-page-loading="{ active: pageLoading, variant: page === 'suppliers' ? 'cards' : 'table', columns: isClinicPurchaseOrders ? 8 : 6, rows: 5 }" class="min-w-0 flex-1 p-4 md:p-8">
