      <p v-if="error" role="alert" class="mb-4 rounded border border-red-500 bg-red-900/30 p-4">{{ error }}</p>
      <p v-if="notice" role="status" class="mb-4 rounded border border-emerald-600 p-4">{{ notice }}</p>
      <p v-if="loading">Loading department records…</p>
      <template v-else>
        <nav v-if="department !== 'finance' && !isClinicPurchaseOrders && tabs.length > 1" class="module-tabs mb-5" role="tablist" :aria-label="`${departmentLabel} sections`"><router-link v-for="tab in tabs" :key="tab.key" :to="tab.to" class="module-tab" role="tab" :aria-selected="tab.key === page" :class="{ 'module-tab-active': tab.key === page }">{{ tab.label }}</router-link></nav>
        <div v-if="page === 'dashboard'" class="space-y-5">
          <div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><article v-for="card in cards" :key="card.label" class="rounded-xl border border-slate-700 bg-slate-800 p-4"><p class="text-sm text-slate-400">{{ card.label }}</p><strong class="mt-2 block text-2xl">{{ card.value }}</strong></article></div>
          <div class="grid gap-4 md:grid-cols-2"><section v-for="chart in charts" :key="chart.title" class="rounded-xl border border-slate-700 p-5"><h2 class="mb-4 font-semibold">{{ chart.title }}</h2><div v-for="entry in chart.entries" :key="entry.label" class="mb-3"><div class="flex justify-between text-sm"><span>{{ entry.label }}</span><span>{{ chart.money ? currency(entry.value) : entry.value }}</span></div><div class="mt-1 h-2 rounded bg-slate-700"><div class="h-2 rounded bg-amber-500" :style="{ width: Math.max(2, 100 * Math.abs(entry.value) / chart.max) + '%' }"></div></div></div><p v-if="!chart.entries.length" class="text-sm text-slate-400">No data recorded yet.</p></section></div>
          <section class="rounded-xl border border-slate-700 p-5"><h2 class="font-semibold">Alerts and next actions</h2><p v-for="alert in alerts" :key="alert" class="mt-2 text-sm text-amber-200">{{ alert }}</p><p v-if="!alerts.length" class="mt-2 text-sm text-slate-400">No outstanding alerts.</p></section>
        </div>
        <template v-else>
          <SupplierDirectory v-if="page === 'suppliers' && department === 'procurement'" embedded />
          <div v-if="!(page === 'suppliers' && department === 'procurement')">
          <template v-if="page === 'budgets' && department === 'finance'">
