              <div class="budget-page-heading"><div><h2>Budget overview</h2><p>Manage and monitor branch purchasing budgets</p></div><button v-if="branchId !== 'all' && can('finance:payables:approve')" class="budget-create" @click="openForm('budget')">＋ Create budget allocation</button></div>
              <div class="budget-summary"><article><span>Total allocated</span><strong>{{ currency(budgetTotals.total) }}</strong></article><article><span>Available</span><strong class="text-emerald-400">{{ currency(budgetTotals.available) }}</strong></article><article><span>Committed</span><strong>{{ currency(budgetTotals.committed) }}</strong></article><article><span>Actual spending</span><strong>{{ currency(budgetTotals.spent) }}</strong></article></div>
              <p class="budget-legend">Available budget = allocated − committed − actual spending.</p>
              <section class="budget-records"><h3>Budget records</h3><div class="budget-filters"><select v-model="budgetBranchFilter" aria-label="Filter budgets by branch"><option value="all">All Assigned Branches</option><option v-for="branch in data.branches" :key="branch.id" :value="branch.id">{{ branch.name }}</option></select><input v-model="budgetPeriod" type="month" aria-label="Budget period" /><input v-model="budgetSearch" placeholder="Search budgets or categories..." aria-label="Search budgets or categories" /></div>
                <div v-if="displayedBudgets.length" class="budget-table-wrap"><table class="budget-table"><thead><tr><th>Branch</th><th>Reference</th><th>Purpose</th><th>Department</th><th>Period</th><th>Allocated</th><th>Committed</th><th>Spent</th><th>Available</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="budget in displayedBudgets" :key="budget.id"><td>{{ branchName(budget.branchId) }}</td><td class="font-semibold">{{ budget.number || budget.id.slice(0, 8) }}</td><td>{{ budget.category || '—' }}</td><td>{{ budget.department || '—' }}</td><td>{{ budget.period || '—' }}</td><td>{{ currency(budget.total) }}</td><td>{{ currency(budget.committed) }}</td><td>{{ currency(budget.spent) }}</td><td class="budget-available-cell">{{ currency(budgetAvailable(budget)) }}</td><td><span class="budget-status" :class="budgetStatusClass(budget.status)">{{ budget.status || 'Active' }}</span></td><td><div class="budget-card-actions"><button class="budget-details" @click="view(budget)">View</button><button v-if="can('finance:payables:approve') && budget.status === 'Active' && !budget.committed && !budget.spent" @click="openForm('editBudget', budget)">Edit</button><button v-if="can('finance:payables:approve') && budget.status === 'Active' && !budget.committed && !budget.spent" class="budget-cancel" @click="openForm('cancelBudget', budget)">Cancel</button></div></td></tr></tbody></table></div><div v-else class="budget-empty-state" role="status"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h4" stroke-linecap="round" stroke-linejoin="round" /></svg><h4>No budget allocations found</h4><p>No budget allocations match these filters. Adjust the branch, period, or search to view other records.</p></div>
              </section>
            </section>
          </template>
          <template v-else>
          <section v-if="page === 'requests' && department === 'finance'" class="mb-5 grid gap-3 md:grid-cols-3"><router-link to="/finance/procurement/requests" class="rounded-xl border border-slate-700 bg-slate-800 p-4"><h2 class="font-semibold">Procurement approvals</h2><p class="mt-2 text-sm text-slate-400">Review funding requests and reserve matching budgets.</p></router-link><router-link to="/finance/listing-approvals" class="rounded-xl border border-slate-700 bg-slate-800 p-4"><h2 class="font-semibold">Listing approvals</h2><p class="mt-2 text-sm text-slate-400">Review listing prices and financial terms.</p></router-link><router-link v-if="canUsePayroll" to="/finance/payroll-approval" class="rounded-xl border border-slate-700 bg-slate-800 p-4"><h2 class="font-semibold">Payroll approvals</h2><p class="mt-2 text-sm text-slate-400">Review HR-prepared payroll summaries.</p></router-link></section>
          <div class="module-actions mb-4">
            <button v-if="department === 'inventory' && page === 'items' && branchId !== 'all' && can('inventory:create')" class="module-action" title="Register a clinic inventory item" @click="openItem()"><span aria-hidden="true">＋</span> Register item</button>
            <button v-if="page === 'requests' && department === 'inventory' && branchId !== 'all' && can('inventory:create')" class="module-action" title="Create inventory request" @click="openForm('request')"><span aria-hidden="true">＋</span> New request</button>
            <button v-if="page === 'budgets' && branchId !== 'all' && can('finance:payables:approve')" class="module-action" title="Create budget" @click="openForm('budget')"><span aria-hidden="true">＋</span> Create budget</button>
            <select v-if="page === 'reports'" v-model="reportKey" aria-label="Report type"><option v-for="(r,index) in availableReports" :key="r.key" :value="index === 0 ? '' : r.key">{{ r.label }}</option></select>
            <div class="workspace-export-controls">
              <ContractAppearanceSelect id="report-export-format" label="Export format" v-model="exportFormat" :disabled="exporting" :options="[{ value: 'csv', label: 'CSV spreadsheet' }, { value: 'pdf', label: 'PDF document' }, { value: 'docx', label: 'Word document' }]" />
              <button type="button" class="module-action" title="Export filtered report" :disabled="exporting" @click="exportReport">{{ exporting ? 'Exporting...' : 'Export report' }}</button>
            </div>
          </div>
          <div v-if="isClinicPurchaseOrders" class="purchase-orders-filters">
            <label class="purchase-orders-search">Search orders<input v-model="search" placeholder="Search order number, supplier, or supply..." /></label>
            <ContractAppearanceSelect id="purchase-orders-status" label="Order status" v-model="status" :options="[{ value: '', label: 'All statuses' }, ...statuses.map(value => ({ value, label: value }))]" />
            <ContractAppearanceSelect id="purchase-orders-supplier" label="Supplier" v-model="supplierFilter" :options="[{ value: '', label: 'All suppliers' }, ...data.suppliers.map(supplier => ({ value: supplier.id, label: supplierName(supplier.id) }))]" />
            <ContractAppearanceSelect id="purchase-orders-sort" label="Sort orders" v-model="sort" :options="[{ value: 'newest', label: 'Newest first' }, { value: 'oldest', label: 'Oldest first' }, { value: 'name', label: 'Order number' }]" />
            <label>Department<input v-model="departmentFilter" placeholder="All departments" /></label>
            <label>Purpose / category<input v-model="categoryFilter" placeholder="All categories" /></label>
            <label>Created from<input type="date" v-model="fromDate" /></label>
            <label>Created through<input type="date" v-model="toDate" /></label>
          </div>
          <div v-else-if="department === 'inventory' && page === 'receiving'" class="inventory-receiving-filters">
            <label class="inventory-receiving-search">Search receiving records<input v-model="search" placeholder="Search reference, supplier, or supply..." /></label>
            <ContractAppearanceSelect id="inventory-receiving-status" label="Status" v-model="status" :options="[{ value: '', label: 'All statuses' }, ...statuses.map(value => ({ value, label: value }))]" />
            <ContractAppearanceSelect id="inventory-receiving-type" label="Record type" v-model="type" :options="[{ value: '', label: 'All record types' }, ...types.map(value => ({ value, label: value === 'po' ? 'Confirmed purchase order' : value === 'discrepancy' ? 'Delivery discrepancy' : 'Delivery inspection' }))]" />
            <ContractAppearanceSelect id="inventory-receiving-supplier" label="Supplier" v-model="supplierFilter" :options="[{ value: '', label: 'All suppliers' }, ...data.suppliers.map(supplier => ({ value: supplier.id, label: supplierName(supplier.id) }))]" />
            <label>From<input type="date" v-model="fromDate" /></label>
            <label>Through<input type="date" v-model="toDate" /></label>
            <ContractAppearanceSelect id="inventory-receiving-sort" label="Sort records" v-model="sort" :options="[{ value: 'newest', label: 'Newest first' }, { value: 'oldest', label: 'Oldest first' }, { value: 'name', label: 'Reference' }]" />
          </div>
          <div v-else class="mb-4 grid gap-2 sm:grid-cols-3 lg:grid-cols-6">
            <input v-model="search" placeholder="Search name, reference, related ID" aria-label="Search records" />
            <select v-model="status"><option value="">All statuses</option><option v-for="value in statuses" :key="value">{{ value }}</option></select>
            <select v-model="type"><option value="">All record types</option><option v-for="value in types" :key="value">{{ value }}</option></select>
            <input v-if="department !== 'finance' || page !== 'invoices'" v-model="departmentFilter" placeholder="Department" aria-label="Department filter" />
            <select v-model="supplierFilter"><option value="">All suppliers</option><option v-for="s in data.suppliers" :key="s.id" :value="s.id">{{ supplierName(s.id) }}</option></select>
            <input v-if="department !== 'finance' || page !== 'invoices'" v-model="categoryFilter" placeholder="Category" aria-label="Category filter" />
            <label class="text-xs text-slate-400">From<input type="date" v-model="fromDate" /></label><label class="text-xs text-slate-400">Through<input type="date" v-model="toDate" /></label>
            <select v-model="sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="name">Name/reference</option></select>
          </div>
          <div v-if="isClinicPurchaseOrders" class="purchase-orders-table-wrap overflow-x-auto rounded-xl border border-slate-700">
            <table class="w-full text-left"><thead><tr><th>Purchase order</th><th>Supplier</th><th>Department</th><th>Delivery date</th><th>Items</th><th>Total</th><th>Status</th><th>Action</th></tr></thead>
              <tbody><tr v-for="order in pagedRows" :key="order.id"><td><strong>{{ order.number || order.id }}</strong><small>{{ branchName(order.branchId) }}</small></td><td>{{ supplierName(order.supplierId) || order.supplierBusinessName || 'Not specified' }}</td><td>{{ order.department || 'Inventory' }}</td><td>{{ shortDate(order.deliveryDate || order.requiredDate) }}</td><td>{{ order.lines?.length || 0 }}</td><td class="purchase-order-amount">{{ currency(order.total) }}</td><td><span class="purchase-orders-status" :class="['Rejected', 'Cancelled', 'Clarification Requested'].includes(order.status) ? 'is-negative' : ['Approved', 'Delivered', 'Completed'].includes(order.status) ? 'is-positive' : 'is-pending'">{{ order.status || 'Pending' }}</span></td><td><button @click="view(order)">View details</button></td></tr><tr v-if="!pagedRows.length"><td colspan="8">No purchase orders match these filters.</td></tr></tbody>
            </table>
          </div>
          <div v-else-if="department === 'inventory' && page === 'receiving'" class="overflow-x-auto rounded-xl border border-slate-700">
            <table class="w-full text-left"><thead><tr><th>Reference</th><th>Record type</th><th>Supplier</th><th>Delivery date</th><th>Status</th><th>Order total</th><th>Action</th></tr></thead><tbody>
              <tr v-for="row in pagedRows" :key="row.id"><td><strong>{{ row.number || row.id }}</strong></td><td>{{ row.kind === 'po' ? 'Confirmed purchase order' : row.kind === 'discrepancy' ? 'Delivery discrepancy' : 'Delivery inspection' }}</td><td>{{ supplierName(row.supplierId) }}</td><td>{{ shortDate(row.deliveryDate) }}</td><td><span class="inventory-receiving-status" :class="['Rejected', 'Cancelled'].includes(row.status) ? 'is-negative' : ['Completed', 'Delivered', 'Inspected', 'Onboarded'].includes(row.status) ? 'is-positive' : 'is-pending'">{{ row.status || 'Pending' }}</span></td><td class="whitespace-nowrap">{{ row.total != null ? currency(row.total) : '?' }}</td><td><button @click="view(row)">View details</button></td></tr>
              <tr v-if="!pagedRows.length"><td colspan="7">No delivery records match these filters.</td></tr>
            </tbody></table>
          </div>
          <div v-else-if="department === 'finance' && page === 'invoices'" class="overflow-x-auto rounded-xl border border-slate-700">
            <table class="w-full text-left"><thead><tr><th>Reference</th><th>Record type</th><th>Supplier</th><th>Branch</th><th>Date</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead>
              <tbody><tr v-for="row in pagedRows" :key="row.id"><td><strong>{{ row.invoiceNumber || row.number || row.id }}</strong></td><td>{{ row.kind === 'invoice' ? 'Invoice' : 'Payment' }}</td><td>{{ supplierName(row.supplierId) }}</td><td>{{ branchName(row.branchId) }}</td><td>{{ shortDate(row.paymentDate || row.invoiceDate || row.createdAt) }}</td><td class="whitespace-nowrap font-semibold">{{ currency(row.total) }}</td><td><span class="budget-status" :class="['Paid', 'Matched', 'Approved'].includes(row.status) ? 'finance-status-success' : ['Disputed', 'Rejected', 'Cancelled'].includes(row.status) ? 'finance-status-danger' : 'finance-status-pending'">{{ row.status }}</span></td><td><button @click="view(row)">View details</button></td></tr><tr v-if="!pagedRows.length"><td colspan="8">No invoices or payments match these filters.</td></tr></tbody>
            </table>
          </div>
          <div v-else class="overflow-x-auto rounded-xl border border-slate-700"><table class="w-full text-left text-sm"><thead class="bg-slate-800"><tr><th>Reference / Item</th><th>Type</th><th>Status / DSS</th><th>Quantity / Amount</th><th></th></tr></thead><tbody><tr v-for="row in pagedRows" :key="row.id" class="border-t border-slate-700"><td><img v-if="row.imageUrl" :src="row.imageUrl" alt="" class="mr-2 inline-block h-10 w-10 rounded object-cover" />{{ row.number || row.name || row.businessName || row.id }}<small class="block text-slate-400">{{ row.brand || row.department || supplierName(row.supplierId) }}</small></td><td>{{ row.kind || row.itemType || 'Supplier' }}</td><td><span class="rounded bg-slate-700 px-2 py-1">{{ row.signals?.join(', ') || row.status || 'In Stock' }}</span></td><td>{{ row.currentStock !== undefined ? row.currentStock + ' ' + (row.unit || 'units') : row.total !== undefined ? currency(row.total) : row.requestedAmount !== undefined ? currency(row.requestedAmount) : row.lines?.map(l => l.quantity ?? l.accepted).join(', ') || '—' }}</td><td class="whitespace-nowrap"><button @click="view(row)">Details</button> <button v-if="department === 'inventory' && page === 'items' && can('inventory:update')" class="ml-2 rounded border border-amber-600 px-2 py-1 text-amber-200" @click="openPharmacySetup(row)">{{ row.pharmacyEnabled ? 'Remove from Pharmacy' : 'Add to Pharmacy' }}</button></td></tr><tr v-if="!pagedRows.length"><td colspan="5" class="text-center text-slate-400">No matching records. Create a request or adjust your filters.</td></tr></tbody></table></div>
          <div class="mt-4 flex items-center justify-between"><span class="text-sm text-slate-400">{{ filteredRows.length }} records · Page {{ currentPage }} / {{ pages }}</span><div class="flex gap-2"><button :disabled="currentPage === 1" @click="currentPage--">Previous</button><button :disabled="currentPage >= pages" @click="currentPage++">Next</button></div></div>
          </template>
          </div>
        </template>
      </template>

      <div v-if="pharmacySetupItem" class="fixed inset-0 z-[70] flex items-center justify-center bg-black/80 p-3" @click.self="pharmacySetupItem = null"><form class="w-full max-w-xl space-y-4 rounded-xl border border-slate-600 bg-slate-900 p-6" @submit.prevent="savePharmacySetup"><header class="flex items-start justify-between gap-4"><div><h2 class="text-xl font-semibold">{{ pharmacySetupItem.pharmacyEnabled ? 'Pharmacy item settings' : 'Add item to Pharmacy' }}</h2><p class="mt-1 text-sm text-slate-400">{{ pharmacySetupItem.name }}</p></div><button type="button" aria-label="Close" @click="pharmacySetupItem = null">×</button></header><p class="text-sm text-slate-300">Choose how this item may be dispensed. Restricted items remain visible in Pharmacy but the POS will block their sale.</p><label class="block text-sm text-slate-300">Dispensing classification<select v-model="pharmacySetup.dispensingClass" class="mt-1 block w-full rounded border border-slate-600 bg-slate-800 p-2 text-white"><option value="unclassified">Unclassified (cannot sell)</option><option value="general_sale">General sale</option><option value="prescription_required">Prescription required</option><option value="restricted">Restricted (POS sale blocked)</option></select></label><p class="text-xs text-slate-400">Prescription required items need a linked completed consultation prescription naming the item. Confirm classification with your clinic’s responsible professional.</p><label class="block text-sm text-slate-300">Retail price (PHP)<input v-model.number="pharmacySetup.retailPrice" type="number" min="0.01" step="0.01" class="mt-1 block w-full rounded border border-slate-600 bg-slate-800 p-2 text-white" /></label><label class="flex items-center gap-2 text-sm text-slate-200"><input v-model="pharmacySetup.enabled" type="checkbox" /> Available in Pharmacy</label><p v-if="pharmacySetupError" class="text-sm text-red-300" role="alert">{{ pharmacySetupError }}</p><div class="flex justify-end gap-3"><button type="button" class="rounded border border-slate-600 px-4 py-2" :disabled="busy" @click="pharmacySetupItem = null">Cancel</button><button class="rounded bg-amber-800 px-4 py-2" type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Save pharmacy settings' }}</button></div></form></div>

      <div v-if="selected" class="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-3" @click.self="selected = null"><section role="dialog" aria-modal="true" :aria-label="selected.kind === 'po' ? 'Purchase order details' : 'Record details'" :class="{ 'po-details-dialog': selected.kind === 'po' }" class="max-h-[92vh] w-full max-w-5xl overflow-auto rounded-xl border border-slate-600 bg-slate-900 p-6"><template v-if="selected.kind === 'budgetRequest'"><header class="flex items-start justify-between gap-4"><div><p class="text-xs text-amber-300">Finance › Approvals › {{ selected.number }}</p><h2 class="mt-1 text-xl font-semibold">Funding Request Details</h2><p class="text-xs text-slate-400">{{ selected.number }}</p></div><div class="flex items-center gap-3"><span class="rounded-full bg-amber-950 px-3 py-1 text-xs text-amber-200">{{ selected.status }}</span><button type="button" aria-label="Close details" class="workspace-dialog-close" @click="selected = null"><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M6 18 18 6" stroke-linecap="round" /></svg></button></div></header><section class="funding-total-card mt-4"><p>Total funding requested</p><strong>{{ currency(selected.requestedAmount) }}</strong><small>{{ branchName(selected.branchId) }}<br />Submitted by Procurement</small></section></template><header v-else class="flex justify-between" :class="{ 'po-details-heading': selected.kind === 'po' }"><div><h2 class="text-xl font-semibold">{{ selected.number || selected.name || selected.businessName }}</h2><p class="text-sm text-amber-200">{{ selected.status || selected.signals?.join(', ') }} · {{ nextAction(selected) }}</p></div><button type="button" aria-label="Close details" class="workspace-dialog-close" @click="selected = null"><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M6 18 18 6" stroke-linecap="round" /></svg></button></header>
        <div v-if="!['budgetRequest', 'po'].includes(selected.kind)" class="my-4 grid gap-3 rounded-lg border border-slate-700 p-4 sm:grid-cols-3"><div><small class="text-slate-400">Current Status</small><p>{{ selected.status || selected.signals?.join(', ') || 'Active' }}</p></div><div><small class="text-slate-400">Responsible Department</small><p>{{ responsibleDepartment(selected) }}</p></div><div v-if="selected.supplierId"><small class="text-slate-400">Supplier Name</small><p>{{ supplierDisplayName(selected) }}</p></div><div v-else><small class="text-slate-400">Current Owner</small><p>{{ currentOwner(selected) }}</p></div></div>
        <PurchaseOrderSummary v-if="selected.kind === 'po'" :record="selected" :supplier-name="supplierDisplayName(selected)" :branch-name="branchName(selected.branchId)" :currency="currency" :delivery-result="deliveryResultFor" />
        <p v-if="error" class="my-3 text-red-300" role="alert">{{ error }}</p><p v-for="issue in selected.matchIssues || []" :key="issue" class="my-2 text-red-300">{{ issue }}</p><div v-if="selected.kind !== 'budgetRequest'" class="my-5 flex flex-wrap gap-2"><button v-if="selected.kind === 'po' && ['Approved', 'Receiving', 'Completed'].includes(selected.status)" type="button" @click="downloadPurchaseOrderPdf(selected)" :disabled="exporting">Download PO PDF</button><button v-for="action in actions(selected)" :key="action.key" @click="runAction(action.key, selected)" :disabled="busy">{{ action.label }}</button></div>
        <section v-if="selected.kind === 'request' && selected.status === 'Returned'" class="my-5 rounded-lg border border-amber-600 bg-black p-4 text-sm"><div class="flex items-start justify-between"><div><h3 class="font-semibold text-white">Inventory Request</h3><p class="mt-1 text-xs text-slate-400">{{ selected.number }}</p></div><span class="rounded bg-amber-950 px-2 py-1 text-xs text-amber-300">Revision Required</span></div><div class="mt-4 border-t border-amber-700/60 pt-4"><h4 class="font-semibold text-amber-200">⚠ Returned by Procurement</h4><p class="mt-3 text-white"><strong>Reason:</strong> {{ selected.returnReason }}</p><p class="mt-2 text-slate-200">{{ selected.returnInstructions }}</p><p class="mt-3 border-t border-slate-800 pt-3 text-xs text-slate-400">Returned by: Procurement Staff</p></div><div class="mt-5 border-t border-slate-800 pt-4"><h4 class="font-semibold text-white">Requested items</h4><div v-for="line in selected.lines" :key="line.itemId" class="mt-3 rounded-lg border border-slate-700 p-3"><p class="font-semibold text-white">{{ line.name }}</p><p class="mt-1 text-xs text-slate-300">{{ supplierName(line.supplierId) }} · {{ currency(line.unitPrice) }} per {{ line.unit }}</p><p class="mt-2 text-xs text-slate-300">Requested quantity: {{ line.quantity }}</p></div></div><button class="mt-5 w-full bg-white text-slate-900" :disabled="busy || selected.createdBy !== data.uid" @click="openForm('resubmit', selected)">Revise &amp; Resubmit</button></section>
        <section v-if="selected.kind === 'procurement'" class="my-5 rounded-lg border border-slate-700 bg-black p-4 text-sm"><div class="flex items-start justify-between border-b border-slate-800 pb-4"><div><h3 class="font-semibold text-white">Procurement Request</h3><p class="mt-1 text-xs text-slate-400">{{ selected.number }}</p></div><span class="rounded bg-amber-950 px-2 py-1 text-xs text-amber-300">{{ selected.status }}</span></div><h4 class="mt-5 font-semibold text-white">Request summary</h4><dl class="mt-3 space-y-3"><div class="flex justify-between gap-4"><dt>Supplier</dt><dd class="font-semibold text-white">{{ selected.supplierId ? supplierName(selected.supplierId) : 'Selected during quotation' }}</dd></div><div class="flex justify-between gap-4"><dt>Requested items</dt><dd class="font-semibold text-white">{{ selected.lines?.length || 0 }} product{{ selected.lines?.length === 1 ? '' : 's' }}</dd></div><div class="flex justify-between gap-4"><dt>Estimated total</dt><dd class="font-semibold text-white">{{ Number(selected.estimatedProcurementValue) > 0 ? currency(selected.estimatedProcurementValue) : 'Not quoted yet' }}</dd></div></dl><div class="mt-5 border-t border-slate-800 pt-4"><h4 class="font-semibold text-white">Procurement checklist</h4><label v-for="check in procurementChecklist" :key="check.key" class="mt-3 flex cursor-pointer items-center gap-2 text-white"><input v-model="procurementChecks[check.key]" type="checkbox" :disabled="busy" />{{ check.label }}</label></div><div class="mt-5 space-y-2 border-t border-slate-800 pt-4"><button class="w-full border-0 bg-amber-700 text-white disabled:opacity-40" :disabled="busy" @click="confirmProcurement">Confirm &amp; Request Budget</button><button class="w-full border-slate-600 bg-transparent text-white" :disabled="busy" @click="openForm('returnInventory', selected)">Return to Inventory</button></div></section>
        <template v-if="selected.kind === 'budgetRequest'"><section class="funding-section"><h3>1. Request information</h3><dl class="funding-panel"><div><dt>Funding Request</dt><dd>{{ selected.number }}</dd></div><div><dt>Procurement Request</dt><dd>{{ fundingProcurement?.number || '—' }}</dd></div><div><dt>Inventory Request</dt><dd>{{ fundingInventoryRequest?.number || '—' }}</dd></div><div><dt>Department</dt><dd>{{ selected.department }}</dd></div><div><dt>Supplier</dt><dd>{{ supplierName(selected.supplierId) }}</dd></div><div><dt>Purpose</dt><dd>{{ fundingInventoryRequest?.reason || fundingProcurement?.reason || 'Restock requested supplies' }}</dd></div></dl></section><section class="funding-section"><h3>2. Requested items</h3><div class="funding-panel"><article v-for="line in selected.lines || []" :key="line.itemId" class="funding-line"><div><strong>{{ line.name || itemName(line.itemId) }}</strong><small>{{ line.quantity }} {{ line.unit }} × {{ currency(line.unitPrice) }}</small></div><b>{{ currency(Number(line.quantity || 0) * Number(line.unitPrice || 0)) }}</b></article><div class="funding-grand"><strong>Grand total</strong><b>{{ currency(selected.requestedAmount) }}</b></div></div></section><section class="funding-section"><h3>3. Budget verification</h3><div v-if="fundingBudget" class="funding-panel funding-budget" :class="{ 'funding-budget-insufficient': budgetAvailable(fundingBudget) < Number(selected.requestedAmount || 0) }"><div class="flex items-center justify-between gap-3"><strong>{{ fundingBudget.category }} Budget</strong><span>{{ budgetAvailable(fundingBudget) >= Number(selected.requestedAmount || 0) ? 'Sufficient' : 'Insufficient' }}</span></div><dl><div><dt>Approved allocation</dt><dd>{{ currency(fundingBudget.total) }}</dd></div><div><dt>Existing commitments</dt><dd>{{ currency(fundingBudget.committed) }}</dd></div><div><dt>Recognized spending</dt><dd>{{ currency(fundingBudget.spent) }}</dd></div><div class="funding-rule"><dt>Available before approval</dt><dd>{{ currency(budgetAvailable(fundingBudget)) }}</dd></div><div><dt>Requested amount</dt><dd>−{{ currency(selected.requestedAmount) }}</dd></div></dl><div class="funding-projected"><small>Projected available budget after approval</small><strong>{{ currency(Math.max(0, budgetAvailable(fundingBudget) - Number(selected.requestedAmount || 0))) }}</strong></div></div><p v-else class="funding-panel text-sm text-red-300">No active budget allocation matches {{ selected.department }} / {{ selected.category }}. Create a matching allocation before approving.</p></section><section class="funding-section"><h3>4. Procurement justification</h3><div class="funding-panel text-sm"><p>{{ fundingInventoryRequest?.reason || fundingProcurement?.reason || 'No additional justification was provided.' }}</p><ul><li>Supplier and prices verified by Procurement</li><li>Request contains complete item details</li><li>Applicable budget identified</li></ul></div></section><section class="funding-section"><h3>5. Supporting records</h3><div class="funding-panel"><button v-if="fundingInventoryRequest" class="funding-link" @click="view(fundingInventoryRequest)"><span>Inventory Request<small>{{ fundingInventoryRequest.number }}</small></span><b>Linked</b></button><button v-if="fundingProcurement" class="funding-link" @click="view(fundingProcurement)"><span>Procurement Request<small>{{ fundingProcurement.number }}</small></span><b>Linked</b></button></div></section><section class="funding-section border-t border-slate-700 pt-4"><h3>6. Finance decision</h3><p class="mb-3 text-sm text-slate-400">Approving reserves the selected budget and creates a Purchase Order for Procurement to issue.</p><p v-if="!canDecideFunding" class="mb-3 text-xs text-amber-200">{{ fundingDecisionNotice }}</p><div class="space-y-2"><button class="funding-decision funding-approve" @click="runAction('approve', selected)" :disabled="busy || !canDecideFunding">✓ Approve Funding</button><button class="funding-decision funding-return" @click="runAction('return', selected)" :disabled="busy || !canDecideFunding">↩ Return for Revision</button><button class="funding-decision funding-reject" @click="runAction('reject', selected)" :disabled="busy || !canDecideFunding">× Reject Request</button></div></section></template>
        <dl v-if="!['budgetRequest', 'po'].includes(selected.kind)" class="grid gap-3 sm:grid-cols-3"><template v-for="[key, value] in detailFields" :key="key"><div><dt class="text-xs text-slate-400">{{ label(key) }}</dt><dd class="break-words text-sm">{{ formatValue(key, value) }}</dd></div></template></dl>
        <img v-if="selected.imageUrl" :src="selected.imageUrl" alt="Inventory item" class="my-4 max-h-48 rounded" />
        <div v-if="!['budgetRequest', 'po'].includes(selected.kind) && selected.lines?.length" class="my-5 overflow-auto"><table class="w-full text-sm"><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Delivered / Accepted / Rejected</th><th>Condition / Notes</th></tr></thead><tbody><tr v-for="line in selected.lines" :key="line.itemId"><td>{{ line.name || itemName(line.itemId) }}</td><td>{{ line.quantity ?? line.ordered }} {{ line.unit }}</td><td>{{ ['request','procurement'].includes(selected.kind) && !Number(line.unitPrice) ? 'Not quoted yet' : line.unitPrice !== undefined ? currency(line.unitPrice) : 'Not recorded' }}</td><td>{{ deliveryResultFor(selected, line).summary }}</td><td>{{ deliveryResultFor(selected, line).notes }}</td></tr></tbody></table></div>
        <section v-if="selected.kind === 'invoice'" class="my-5 rounded-lg border border-slate-700 p-4">
          <h3 class="font-semibold">Supplier invoice price breakdown</h3>
          <dl class="mt-3 grid gap-2 sm:grid-cols-2"><div><dt>Items subtotal</dt><dd>{{ currency(selected.subtotal) }}</dd></div><div v-for="adjustment in quoteAdjustmentRows(selected)" :key="adjustment.key"><dt>{{ adjustment.label }}</dt><dd>{{ adjustment.type === 'discount' ? '−' : '' }}{{ currency(adjustment.amount) }}</dd></div><div v-if="selected.statedTotal != null"><dt>Supplier-stated total</dt><dd>{{ currency(selected.statedTotal) }}</dd></div><div><dt>Calculated invoice total</dt><dd>{{ currency(selected.total) }}</dd></div></dl>
          <p v-if="quoteTaxTreatmentLabel(quoteTaxTreatment(selected))" class="mt-2 text-xs text-slate-400">{{ quoteTaxTreatmentLabel(quoteTaxTreatment(selected)) }}.</p>
        </section>        <section v-if="selected.kind === 'rfq'" class="my-5"><h3 class="font-semibold">Historical quotation comparison</h3><div class="overflow-auto"><table class="w-full text-sm"><thead><tr><th>Supplier</th><th>Total</th><th>Lead days</th><th>Payment terms</th><th>Warranty</th><th>Valid until</th></tr></thead><tbody><tr v-for="q in data.records.filter(r => r.kind === 'quotation' && r.rfqId === selected.id)" :key="q.id"><td><button @click="view(q)">{{ supplierName(q.supplierId) }}</button></td><td>{{ currency(q.total) }}</td><td>{{ q.leadDays }}</td><td>{{ q.paymentTerms }}</td><td>{{ q.warranty }}</td><td>{{ q.validUntil }}</td></tr></tbody></table></div></section>
        <section v-if="!selected.kind && selected.currentStock === undefined" class="my-5"><h3 class="font-semibold">Clinic supplier contact</h3><dl class="mt-3 grid gap-3 sm:grid-cols-2"><div><dt>Contact person</dt><dd>{{ selected.contactPerson || 'Not recorded' }}</dd></div><div><dt>Email</dt><dd>{{ selected.email || 'Not recorded' }}</dd></div><div><dt>Phone</dt><dd>{{ selected.contactNumber || selected.phone || 'Not recorded' }}</dd></div><div><dt>Category</dt><dd>{{ selected.category || 'Not recorded' }}</dd></div></dl></section>
        <component :is="selected.kind === 'po' ? 'details' : 'div'" :key="selected.id" :class="{ 'po-supporting-details': selected.kind === 'po' }">
          <summary v-if="selected.kind === 'po'">Documents, messages &amp; activity</summary>
        <section v-if="selected.kind !== 'budgetRequest'" class="my-5"><h3 class="font-semibold">Related records</h3><div class="mt-2 flex flex-wrap gap-2"><button v-for="r in relatedRecords" :key="r.id" @click="view(r)">{{ r.number || r.name || r.id }} · {{ r.status }}</button></div></section>
        <section v-if="selected.kind !== 'budgetRequest' && data.records.some(r => r.id === selected.id)"><h3 class="font-semibold">Documents</h3><p class="mt-1 text-sm text-slate-400">{{ documentGuidance }}</p><div class="my-2 flex flex-wrap gap-2"><button v-for="d in history.documents" :key="d.id" @click="download(d)">{{ d.name }} · {{ d.visibility }}</button></div><label class="text-sm">Upload PDF or image (up to 5 MB)<input type="file" accept="application/pdf,image/png,image/jpeg" @change="upload" :disabled="busy" /></label><p class="my-2 text-xs text-slate-400">Documents remain internal. Procurement sends approved PO documents through its normal external channel.</p></section>
        <section v-if="history.messages?.length || ['rfq','po'].includes(selected.kind)" class="mt-5"><div class="flex items-center justify-between gap-3"><div><h3 class="font-semibold">External communication log</h3><p class="text-xs text-slate-400">Clinic staff record communication handled outside AesthetiCare for this {{ selected.kind === 'po' ? 'Purchase Order' : 'historical RFQ' }}.</p></div><button v-if="actions(selected).some(action => action.key === 'message')" @click="openForm('message', selected)">Record communication</button></div><div class="record-message-thread"><article v-for="m in history.messages" :key="m.id" class="record-message" :class="m.from === 'Supplier' ? 'record-message-supplier' : 'record-message-clinic'"><p>{{ m.message }}</p><small>{{ m.from }} · {{ m.channel }} · {{ formatDate(m.createdAt) }}</small></article><p v-if="!history.messages?.length" class="py-4 text-center text-sm text-slate-400">No messages on this record yet.</p></div></section><section v-if="history.history.length" class="mt-5"><h3 class="font-semibold">Activity timeline</h3><p v-for="event in history.history" :key="event.id" class="mt-2 border-l-2 border-amber-500 pl-3 text-sm">{{ formatDate(event.createdAt) }} · {{ event.actorName || event.actorId }} · {{ event.action }} · {{ event.previousStatus }} → {{ event.newStatus }}</p></section>
          <details v-if="selected.kind === 'po'" class="po-extra-details"><summary>Additional order information</summary><dl class="grid gap-3 sm:grid-cols-2"><div v-for="[key, value] in detailFields" :key="key"><dt class="text-xs text-slate-400">{{ label(key) }}</dt><dd class="break-words text-sm">{{ formatValue(key, value) }}</dd></div></dl></details>
        </component>
      </section></div>

      <div v-if="formKind" class="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 p-3"><form @submit.prevent="saveForm" class="max-h-[92vh] w-full max-w-4xl overflow-auto rounded-xl border border-slate-600 bg-slate-900 p-6"><template v-if="formKind === 'budget'"><header class="budget-modal-heading"><div><h2>⊕ Create Budget Allocation</h2><p>Set a purchasing budget for a specific branch and period.</p></div><button type="button" aria-label="Close" @click="formKind = ''">×</button></header><p v-if="formError" class="mb-3 text-red-300" role="alert">{{ formError }}</p><div class="budget-modal-fields"><label>Branch <em>*</em><select v-model="form.branchId" required><option value="">Select branch</option><option v-for="branch in data.branches" :key="branch.id" :value="branch.id">{{ branch.name }}</option></select></label><label>Department <em>*</em><select v-model="form.department" required><option>Inventory</option><option>Procurement</option><option>Clinic Operations</option></select><small>Must match the department on the funding request.</small></label><label>Purpose <em>*</em><input v-model.trim="form.category" required maxlength="120" placeholder="e.g. Medical supplies replenishment" /><small>Use a clear purpose that matches the related purchasing request when this budget will fund one.</small></label><label>Budget period <em>*</em><input v-model="form.period" type="month" required /><small>Use the selected budgeting period from the main page.</small></label><label>Allocated amount (PHP) <em>*</em><input v-model.number="form.total" type="number" min="0.01" step="0.01" required placeholder="Enter amount" /></label><label>Notes <span>(optional)</span><textarea v-model.trim="form.notes" rows="3" placeholder="Additional context or allocation notes..."></textarea></label></div><div class="mt-6 flex justify-end gap-3"><button type="button" @click="formKind = ''" :disabled="busy">Cancel</button><button class="bg-amber-800" type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Create allocation' }}</button></div></template><template v-else><h2 class="mb-4 text-xl font-semibold">{{ formTitle }}</h2><p v-if="formError" class="mb-3 text-red-300" role="alert">{{ formError }}</p><aside v-if="formKind === 'approve' && formTarget?.kind === 'budgetRequest'" class="mb-4 rounded-lg border border-amber-500/40 bg-amber-950/30 p-3 text-sm"><p class="font-semibold text-amber-200">Approve against an allocated budget</p><p class="mt-1 text-slate-300">Choose an active budget with the same department and purpose. Finance can approve only up to its available balance.</p><p v-if="selectedApprovalBudget" class="mt-2 text-emerald-300">Available in selected budget: {{ currency(budgetAvailable(selectedApprovalBudget)) }}</p><p v-else-if="!matchingBudgetOptions.length" class="mt-2 text-red-300">No matching active budget is available. Create a Budget Allocation first.</p></aside>
        <p v-if="formKind === 'ship'" class="mb-4 rounded-lg border border-sky-500/40 bg-sky-950/30 p-3 text-sm text-sky-100">Use this after the order leaves your facility. The dispatch date is required; carrier, tracking/reference, and notes are optional but help the clinic prepare for delivery.</p><div v-if="formKind !== 'request'" class="grid gap-4 sm:grid-cols-2"><label v-for="field in formFields" :key="field.key" class="text-sm text-slate-300">{{ field.label }}<select v-if="field.options" v-model="form[field.key]" :multiple="field.multiple" :required="field.required !== false"><option v-if="!field.multiple" value="">Select…</option><option v-for="option in field.options" :key="option.value ?? option" :value="option.value ?? option">{{ option.label ?? option }}</option></select><textarea v-else-if="field.type === 'textarea'" v-model="form[field.key]" :placeholder="field.placeholder" :required="field.required !== false" :readonly="field.readOnly" rows="3"></textarea><input v-else v-model="form[field.key]" :type="field.type || 'text'" :placeholder="field.placeholder" :required="field.required !== false" :disabled="field.readOnly" :min="field.type === 'number' ? 0 : undefined" :step="field.type === 'number' ? 'any' : undefined" /></label></div>
        <section v-if="formKind === 'request'" class="mt-2 space-y-5"><p class="-mt-3 text-sm text-slate-400">Describe the item need. Procurement will choose a clinic supplier and record the externally received quotation.</p><div class="grid gap-3 sm:grid-cols-2"><label>Supply or item name <span class="text-red-300">*</span><input v-model.trim="requestDraft.name" required maxlength="200" /></label><label>Category <span class="text-red-300">*</span><input v-model.trim="requestDraft.category" required maxlength="120" placeholder="e.g. Consumable, medication, equipment" /></label><label>Unit<input v-model.trim="requestDraft.unit" maxlength="40" placeholder="units" /></label><label>Quantity <span class="text-red-300">*</span><input v-model.number="requestDraft.quantity" type="number" min="1" step="1" required /></label><label class="sm:col-span-2">Specifications<textarea v-model.trim="requestDraft.specifications" rows="2" maxlength="4000" placeholder="Brand, size, formulation, or other requirements"></textarea></label><button type="button" class="justify-self-start" @click="addRequestLine">Add item to request</button></div><div v-if="form.lines?.length" class="space-y-2"><h3 class="font-semibold">Requested items</h3><article v-for="line in form.lines" :key="line.itemId" class="flex items-start justify-between gap-3 rounded border border-slate-700 p-3"><div><strong>{{ line.name }}</strong><p class="text-sm text-slate-400">{{ line.category }} · {{ line.quantity }} {{ line.unit }}<span v-if="line.specifications"> · {{ line.specifications }}</span></p></div><button type="button" @click="removeRequestLine(line.itemId)">Remove</button></article></div><div class="grid gap-3 border-t border-slate-700 pt-4 sm:grid-cols-2"><label>Priority<select v-model="form.priority"><option v-for="priority in ['Low','Normal','High','Urgent']" :key="priority">{{ priority }}</option></select></label><label>Required date<input v-model="form.requiredDate" type="date" required /></label><label class="sm:col-span-2">Delivery location<input v-model.trim="form.location" maxlength="500" placeholder="Branch or storage room" /></label><label class="sm:col-span-2">Reason for request <span class="text-red-300">*</span><textarea v-model.trim="form.reason" rows="3" required placeholder="Describe the stock need."></textarea></label><label class="sm:col-span-2">Additional notes<textarea v-model.trim="form.notes" rows="2"></textarea></label></div></section>
              <div v-if="form.lines && formKind !== 'request'" class="mt-5 space-y-3"><h3 class="font-semibold">{{ formKind === 'receiving' ? 'Quantity and quality inspection' : 'Line items' }}</h3><p v-if="formKind === 'prepareFunding'" class="text-sm text-slate-400">Enter prices and terms from the attached supplier quotation. Quantities must match the Inventory request.</p><div v-for="line in form.lines" :key="line.itemId" class="rounded border border-slate-700 p-3"><p class="mb-2 font-medium">{{ line.name || itemName(line.itemId) }}</p><div class="grid gap-2 sm:grid-cols-3"><template v-if="formKind === 'receiving'"><label>Delivered<input type="number" min="0" step="1" v-model="line.delivered" required /></label><label>Accepted<input type="number" min="0" step="1" v-model="line.accepted" required /></label><label>Rejected<input type="number" min="0" step="1" v-model="line.rejected" required /></label><label>Condition<select v-model="line.condition"><option v-for="c in ['Good','Damaged','Defective','Wrong item','Expired','Missing','Other discrepancy']" :key="c">{{ c }}</option></select></label><label>Reason / discrepancy<input v-model="line.reason" /></label><label>Batch / lot<input v-model="line.lot" /></label><label>Manufacturing date<input type="date" v-model="line.manufacturingDate" /></label><label>Expiry<input type="date" v-model="line.expiryDate" :min="line.manufacturingDate || undefined" /></label><label>Serial number<input v-model="line.serialNumber" /></label><label>Model<input v-model="line.modelNumber" /></label><label>Warranty<input v-model="line.warranty" /></label><label>Packaging<input v-model="line.packaging" /></label></template><template v-else><label>Quantity<input type="number" min="1" step="1" v-model="line.quantity" :disabled="formKind === 'prepareFunding'" required /></label><label>Unit price (PHP)<input type="number" min="0" step="0.01" v-model="line.unitPrice" :disabled="false" required /></label><p class="self-end pb-2">₱{{ (Number(line.quantity || 0) * Number(line.unitPrice || 0)).toFixed(2) }}</p></template></div></div><p v-if="formKind !== 'receiving' && !isQuotePricingForm" class="text-right font-semibold">Total: ₱{{ formTotal.toFixed(2) }}</p></div>
<section v-if="isQuotePricingForm" class="mt-5 space-y-4 rounded-lg border border-slate-700 bg-slate-900/60 p-4">
  <div><h3 class="font-semibold">{{ ['invoice', 'reviseInvoice'].includes(formKind) ? 'Invoice pricing' : 'Quote pricing' }}</h3><p class="mt-1 text-sm text-slate-400">Copy amounts from the supplier document. The system checks the total; it does not calculate tax rates.</p></div>
  <label class="block text-sm text-slate-300">How does the supplier show tax?<select v-model="form.taxTreatment" class="mt-1 w-full"><option value="included">Tax is already included in item prices</option><option value="separate">Tax is listed as a separate amount</option><option value="not-applicable">No tax applies to this document</option></select></label>
  <p class="text-xs text-slate-400">If tax is included in item prices, do not add another tax amount below. If tax is separate, enter the amount shown on the document.</p>
  <div class="space-y-2"><div class="flex flex-wrap items-center justify-between gap-2"><div><h4 class="text-sm font-semibold">Other charges or discounts <span class="font-normal text-slate-400">(optional)</span></h4><p class="text-xs text-slate-400">Examples: VAT, delivery, handling, or supplier discount.</p></div><button type="button" class="rounded border border-slate-600 px-3 py-2 text-sm" @click="addFormAdjustment">Add a charge or discount</button></div>
  <p v-if="!form.adjustments.length" class="rounded border border-dashed border-slate-700 px-3 py-2 text-sm text-slate-400">No extra charges or discounts added.</p>
  <div v-for="(adjustment, index) in form.adjustments" :key="adjustment.id" class="grid gap-2 rounded border border-slate-700 p-3 sm:grid-cols-[1fr_1.5fr_1fr_auto]">
    <label class="block text-sm text-slate-300">Charge type<select v-model="adjustment.type" class="mt-1 w-full"><option value="tax">Tax</option><option value="fee">Fee</option><option value="discount">Discount</option></select></label>
