  const matches = sourceLines.filter(item => String(item.itemId || '') === String(line.itemId || ''))
  if (!matches.length) return { summary: 'Awaiting Inventory inspection', notes: '—' }
  const delivered = matches.reduce((total, item) => total + Number(item.delivered || 0), 0)
  const accepted = matches.reduce((total, item) => total + Number(item.accepted || 0), 0)
  const rejected = matches.reduce((total, item) => total + Number(item.rejected || 0), 0)
  const notes = matches.map(item => [item.condition, item.reason].filter(Boolean).join(': ')).filter(Boolean).join(' · ')
  return { summary: `${delivered} / ${accepted} / ${rejected}`, notes: notes || 'No inspection notes' }
