const connectedWorkflowRecords = computed(() => {
  const selectedRecord = selected.value
  if (!selectedRecord) return []
  const source = [...data.value.records, ...data.value.movements]
  const ids = new Set([selectedRecord.id])
  const itemIds = new Set(selectedRecord.currentStock !== undefined ? [selectedRecord.id] : [])
  let changed = true
  while (changed) {
    changed = false
    for (const record of source) {
      const linked = ids.has(record.id) || (record.links || []).some(id => ids.has(id)) || workflowRelationKeys.some(key => ids.has(record[key])) || (itemIds.size > 0 && (itemIds.has(record.inventoryItemId) || record.lines?.some(line => itemIds.has(line.itemId))))
