  if(kind==='verifyRequest'){form.value={productsCorrect:false,quantitiesVerified:false,availabilityConfirmed:false,pricesVerified:false};f.push(selectField('productsCorrect','Requested products are correct',[{value:true,label:'Confirmed'}]),selectField('quantitiesVerified','Quantities have been verified',[{value:true,label:'Confirmed'}]),selectField('availabilityConfirmed','Supplier availability is confirmed',[{value:true,label:'Confirmed'}]),selectField('pricesVerified','Prices have been verified',[{value:true,label:'Confirmed'}]))}
