  if(kind==='returnInventory')form.value={returnReason:'',otherReturnReason:'',itemId:'',instructions:''}
  if(kind==='supplier')f.push(field('name','Company name'),field('contactPerson','Contact person'),field('email','Email','email',false),field('phone','Phone','text',false),field('address','Address','textarea',false),field('category','Category','text',false),field('registrationNumber','Business registration','text',false));
  if(kind==='budget') form.value={branchId:branchId.value === 'all' ? '' : branchId.value,department:'Inventory',category:'',period:budgetPeriod.value,total:'',notes:''}
  if(kind==='editBudget'){form.value={department:'Inventory',category:target.category,period:target.period||'',total:Number(target.total||0)/100,notes:target.notes||''};f.push(field('category','Purpose'),field('period','Budget period'),field('total','Allocated amount (PHP)','number'),field('notes','Notes','textarea',false))}
  if(kind==='cancelBudget')f.push(field('remarks','Cancellation reason','textarea'))
  if(kind==='rfq'){const eligibleSuppliers=procurementSupplierOptions(target);form.value={mode:'Manual',supplierIds:eligibleSuppliers.filter(s=>target.lines?.some(line=>(line.preferredSupplierId||line.supplierId)===s.value)).map(s=>s.value),deliveryDate:target.requiredDate,deadline:today()};f.push(selectField('supplierIds','Suppliers contacted externally',eligibleSuppliers,true),field('deadline','Quotation response deadline','date'),field('deliveryDate','Required delivery date','date'),field('deliveryLocation','Delivery location'),field('terms','Terms and specifications','textarea'),field('conditions','Conditions','textarea',false),field('contact','Clinic contact'),field('method','External communication method'),field('strategy','Supplier selection notes','textarea'))}
  if(['quotation','revise','invoice','reviseInvoice'].includes(kind)){
    const quoteSupplierId=target.supplierId||target.supplierIds?.[0]||''
    const revisingExistingPrice=kind==='revise'||kind==='reviseInvoice'
    form.value={lines:target.lines.map(l=>({...l,unitPrice:Number(l.unitPrice||0)/100})),adjustments:quoteAdjustmentDrafts(target),taxTreatment:quoteTaxTreatment(target),statedTotal:revisingExistingPrice?Number(target.statedTotal??target.total??0)/100:'',validUntil:target.validUntil||today(),leadDays:target.leadDays||0,paymentTerms:target.paymentTerms||'',warranty:target.warranty||'',invoiceNumber:target.invoiceNumber||'',invoiceDate:today(),supplierId:quoteSupplierId}
    if(kind==='quotation')f.push(selectField('supplierId','Supplier',supplierOptions().filter(s=>target.supplierIds?.includes(s.value))))
    if(kind==='invoice'||kind==='reviseInvoice')f.push(field('invoiceNumber','Supplier invoice number'),field('invoiceDate','Invoice date','date'))
    else f.push(field('validUntil','Quotation valid until','date'),field('leadDays','Delivery lead time (days)','number'),field('paymentTerms','Payment terms'),field('warranty','Warranty','text',false),field('notes','Notes / availability','textarea',false))
