const formTitle=computed(()=>formKind.value==='item'?'Inventory item':formKind.value==='returnInventory'?'Return for Revision':label(formKind.value)+' '+(formTarget.value?.number||''))
const returnReasons=['Incorrect requested quantity','Incorrect product selection','Supplier or product unavailable','Price requires verification','Missing request information','Other']
const quotePricingKinds=['prepareFunding','quotation','revise','invoice','reviseInvoice']
const isQuotePricingForm=computed(()=>quotePricingKinds.includes(formKind.value))
const formTotal=computed(()=>quoteDraftTotal(form.value.lines||[],form.value.adjustments||[]))
const formPricingValid=computed(()=>quoteDraftIsValid(form.value.lines||[],form.value.adjustments||[],form.value.taxTreatment,form.value.statedTotal))
const formItemsSubtotal=computed(()=>(form.value.lines||[]).reduce((sum,line)=>sum+Number(line.quantity||0)*Number(line.unitPrice||0),0))
const formPositiveAdjustments=computed(()=>(form.value.adjustments||[]).filter(row=>row.type!=='discount').reduce((sum,row)=>sum+Number(row.amount||0),0))
const formDiscounts=computed(()=>(form.value.adjustments||[]).filter(row=>row.type==='discount').reduce((sum,row)=>sum+Number(row.amount||0),0))
const formPricingMessage=computed(()=>{
  const lines=form.value.lines||[], adjustments=form.value.adjustments||[]
  if(!lines.length||lines.some(line=>!Number.isFinite(Number(line.unitPrice))||Number(line.unitPrice)<=0))return 'Enter a unit price for every item.'
  if(adjustments.some(row=>!Number.isFinite(Number(row.amount||0))||Number(row.amount||0)<0))return 'Enter a valid amount for each charge or discount.'
  if(adjustments.some(row=>Number(row.amount||0)>0&&!String(row.label||'').trim()))return 'Add a description for each charge or discount with an amount.'
  if(form.value.taxTreatment!=='separate'&&adjustments.some(row=>row.type==='tax'&&Number(row.amount||0)>0))return 'Set tax to “Tax is listed as a separate amount” or remove the separate tax amount.'
  if(!Number(form.value.statedTotal)||Number(form.value.statedTotal)<=0)return 'Enter the final total shown on the supplier document.'
  const difference=Math.abs(Number(form.value.statedTotal)-formTotal.value)
  if(Math.round(difference*100)>0)return `The totals differ by ₱${difference.toFixed(2)}. Check the item prices and document charges.`
  return 'Check the amounts against the supplier document.'
})
const addFormAdjustment=()=>form.value.adjustments.push({id:`adjustment-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type:'fee',label:'',amount:0})
const removeFormAdjustment=index=>form.value.adjustments.splice(index,1)
const runAction=async(action,target)=>{
  if(action==='editItem')return openItem(target)
  if(action==='requestItem')return openForm('request',target)
  if(action==='settlePayment'){const invoice=invoiceForPayment(target);if(!invoice){error.value='The linked invoice is unavailable.';return}try{history.value=await api(`/records/${target.id}/history`)}catch(e){error.value=e.message;return}return openForm('pay',invoice)}
  if(['editBudget','cancelBudget','editRequest','editRfq','resource','message','rfq','quotation','revise','reviseInvoice','select','receiving','invoice','pay','return','reject','resubmit','confirm','decline','ship','clarify','resend','cancel','resolve','approvePayment','rejectPayment','resubmitPayment','verifyRequest','prepareFunding','returnInventory'].includes(action)||(action==='approve'&&['budgetRequest','po'].includes(target.kind))||(action==='submit'&&target.status==='Returned'))return openForm(action,target)
  const answer=await Swal.fire({title:label(action)+' '+target.number+'?',text:'This action updates the linked workflow records.',icon:'question',showCancelButton:true,confirmButtonText:'Confirm'})
  if(!answer.isConfirmed)return
  busy.value=true;try{await api(`/records/${target.id}/actions`,{action});notice.value=workflowToastMessage(action,target);toast.success(notice.value);await load(true);if(selected.value)await view(selected.value)}catch(e){error.value=e.message;toast.error(error.value)}finally{busy.value=false}
}
const saveForm=async()=>{if(formKind.value==='request'&&!form.value.lines?.length){formError.value='Add at least one supply before submitting.';toast.error(formError.value);return}busy.value=true;formError.value='';try{const kind=formKind.value,target=formTarget.value;let path='/records',body={...form.value,kind,branchId:kind==='budget' ? form.value.branchId : target?.branchId||branchId.value};if(kind==='request')body.action=requestSubmission.value==='draft'?'saveDraft':'create';if(kind==='returnInventory'&&form.value.returnReason==='Other')body.returnReason=form.value.otherReturnReason;if(kind==='message'){path='/records/'+target.id+'/messages';body={...form.value}}else if(kind==='supplier'){path='/suppliers'}else if(kind==='item'){path='/items';body={...form.value,branchId:branchId.value,...(target?{id:target.id}:{})}}else if(['rfq','quotation','receiving','invoice'].includes(kind)){body[kind==='rfq'?'procurementId':kind==='quotation'?'rfqId':'poId']=target.id}else if(!['request','budget'].includes(kind)){path=`/records/${target.id}/actions`;body={...form.value,action:['verifyRequest','prepareFunding'].includes(kind)?'confirm':kind==='returnInventory'?'return':kind}}await api(path,body);formKind.value='';notice.value=kind==='request'?(requestSubmission.value==='draft'?'Request saved as a private draft.':'Request sent to Procurement.'):kind==='receiving'?'Delivery inspected. Inventory must onboard the accepted quantities before stock changes.':workflowToastMessage(kind,target);toast.success(notice.value);await load(true);if(selected.value)await view(selected.value)}catch(e){formError.value=e.message;toast.error(formError.value)}finally{busy.value=false}}
const upload=async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){error.value='File must be 5 MB or smaller.';return}busy.value=true;try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api(`/records/${selected.value.id}/documents`,{name:file.name,contentType:file.type,data:base64,visibility:'internal'});await view(selected.value)}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}
const download=async document=>{try{const result=await api('/documents/'+document.id);window.open(result.url,'_blank','noopener,noreferrer')}catch(e){error.value=e.message}}
const downloadPurchaseOrderPdf = async record => {
  exporting.value = true
  try {
    const headers = ['Item', 'Quantity', 'Unit price', 'Line total']
    const rows = (record.lines || []).map(line => [
      line.name || 'Unnamed item',
      `${line.quantity || 0} ${line.unit || ''}`.trim(),
      currency(line.unitPrice),
      currency(Number(line.quantity || 0) * Number(line.unitPrice || 0)),
    ])
    rows.push(['Subtotal', '', '', currency(record.subtotal)])
    const treatmentLabel = quoteTaxTreatmentLabel(quoteTaxTreatment(record))
    if (treatmentLabel) rows.push(['Tax treatment', '', '', treatmentLabel])
    for (const adjustment of quoteAdjustmentRows(record)) {
      const amount = currency(adjustment.amount)
      rows.push([adjustment.label, '', '', adjustment.type === 'discount' ? `-${amount}` : amount])
    }
    if (record.statedTotal != null) rows.push(['Supplier-stated total', '', '', currency(record.statedTotal)])
    rows.push(['Grand total', '', '', currency(record.total)])
    const blob = await createReportFile('pdf', {
      title: `Purchase Order ${record.number || record.id}`,
      description: `Supplier: ${supplierDisplayName(record)} | Branch: ${branchName(record.branchId)} | Status: ${record.status}`,
      headers,
      rows,
    })
    downloadReport(blob, `${record.number || record.id}.pdf`)
  } catch (e) {
    error.value = e.message
  } finally {
    exporting.value = false
  }
}
const exportReport = async () => {
  if (exporting.value) return
  exporting.value = true
  try {
    const records = filteredRows.value
    let headers, reportRows
    const money = value => currency(value).replace('?', 'PHP ')
    if (department.value === 'finance' && page.value === 'invoices') {
      headers = ['Reference', 'Record type', 'Supplier', 'Branch', 'Date', 'Amount', 'Status']
      reportRows = records.map(row => [row.invoiceNumber || row.number || row.id, row.kind === 'invoice' ? 'Invoice' : 'Payment', supplierName(row.supplierId), branchName(row.branchId), shortDate(row.paymentDate || row.invoiceDate || row.createdAt), money(row.total), row.status || ''])
    } else {
      headers = ['Reference / Item', 'Type', 'Status', 'Quantity / Amount']
      reportRows = records.map(row => [row.number || row.name || row.businessName || row.id, row.kind || row.itemType || 'Supplier', row.signals?.join(', ') || row.status || 'In Stock', row.currentStock != null ? row.currentStock + ' ' + (row.unit || 'units') : row.total != null ? money(row.total) : row.requestedAmount != null ? money(row.requestedAmount) : row.lines?.map(line => line.quantity ?? line.accepted).join(', ') || ''])
    }
    const reportTitle = page.value === 'reports' ? (availableReports.value.find(report => report.key === reportKey.value) || availableReports.value[0])?.label || pageTitle.value : pageTitle.value
    const scope = branchId.value === 'all' ? 'All assigned branches' : branchName(branchId.value)
    const filters = [search.value && 'Search: ' + search.value, status.value && 'Status: ' + status.value, type.value && 'Type: ' + type.value, supplierFilter.value && 'Supplier: ' + supplierName(supplierFilter.value), departmentFilter.value && 'Department: ' + departmentFilter.value, categoryFilter.value && 'Category: ' + categoryFilter.value, fromDate.value && 'From: ' + fromDate.value, toDate.value && 'Through: ' + toDate.value].filter(Boolean)
    const description = [scope, 'Generated ' + today(), records.length + ' records', ...filters].join(' | ')
    const blob = await createReportFile(exportFormat.value, { title: reportTitle, description, headers, rows: reportRows })
    downloadReport(blob, department.value + '-' + page.value + '-' + today() + '.' + exportFormat.value)
  } catch (error) { toast.error(error.message || 'Unable to export this report. Please try again.') }
  finally { exporting.value = false }
}
let timer
onMounted(trackPageLoad(async()=>{await load();timer=setInterval(()=>{if(!busy.value&&!formKind.value)load(true)},60000)}))
onUnmounted(()=>clearInterval(timer))
</script>

